//! The mutations of `cargo xtask mutants`: for each detection, a change that removes it and the
//! test that must then fail.
//!
//! Each mutation finds a text that occurs exactly once in its file and replaces it. For Rust,
//! the test is the name of a test function; for TypeScript, a part of the full name of a test,
//! or the name of a test file.

use super::Mutation;

fn m(name: &str, file: &str, find: &str, replace: &str, test: &str) -> Mutation {
    Mutation {
        name: name.to_string(),
        file: file.to_string(),
        find: find.to_string(),
        replace: replace.to_string(),
        test: test.to_string(),
    }
}

